function newItem(data){return{id:crypto.randomUUID(),group:state.group,...data}}
svg.addEventListener('click',ev=>{if(sheet.hidden||state.tool==='pan'||state.tool==='pen')return;const raw=rawPt(ev);if(state.tool==='select'){if(performance.now()-state.justDragged<250)return;const it=hitItem(raw);state.selected=it?.id||null;refreshUI();return}const snap=snapPoint(raw),p=snap.point;state.snapMarker=snap.snapped?p:null;if(state.tool==='count'){const seq=pageItems().filter(i=>i.type==='count').length+1;state.items.push(newItem({type:'count',page:state.page,points:[p],seq}));refreshUI();return}state.draft.push(p);if(state.tool==='angle'&&state.draft.length===3){finishShape('angle');return}if(state.tool==='multilength'&&state.draft.length===2){let group=state.items.find(i=>i.id===state.multiId);if(!group){group=newItem({type:'multilength',page:state.page,segments:[]});state.items.push(group);state.multiId=group.id}group.segments.push([...state.draft]);state.draft=[];refreshUI();toast('Segment added — '+group.segments.length+' total');return}if(state.tool==='calibrate'&&state.draft.length===2){state.calPts=[...state.draft];$('#scaleModal').classList.add('show');$('#knownValue').focus()}renderOverlay()});
svg.addEventListener('dblclick',ev=>{ev.preventDefault();if(state.tool==='length'&&state.draft.length>=2)finishShape('length');if(state.tool==='area'&&state.draft.length>=3)finishShape('area');if(state.tool==='joint'&&state.draft.length>=2)finishShape('joint')});
function finishShape(type){state.items.push(newItem({type,page:state.page,points:[...state.draft],seq:type==='joint'?state.items.filter(i=>i.type==='joint').length+1:undefined}));state.draft=[];refreshUI();toast(type==='area'?'Area added':type==='angle'?'Angle added':type==='joint'?'Expansion joint added':'Length added')}
svg.addEventListener('pointerdown',ev=>{if(state.tool==='select'){const ref=nearestVertex(rawPt(ev));if(ref){state.dragRef=ref;state.selected=ref.item.id;state.drawing=true;svg.setPointerCapture(ev.pointerId);renderOverlay()}return}if(state.tool==='pen'){state.drawing=true;state.draft=[rawPt(ev)];svg.setPointerCapture(ev.pointerId)}if(state.tool==='pan'){state.drawing=true;state.pan={x:ev.clientX,y:ev.clientY,l:$('#stageWrap').scrollLeft,t:$('#stageWrap').scrollTop};svg.setPointerCapture(ev.pointerId)}});
svg.addEventListener('pointermove',ev=>{const raw=rawPt(ev);let cursor=raw;if(state.tool==='select'&&state.drawing&&state.dragRef){const snap=snapPoint(raw,state.dragRef);cursor=snap.point;setRefPoint(state.dragRef,cursor);state.snapMarker=snap.snapped?cursor:null;renderOverlay()}else if(!['select','pan','pen'].includes(state.tool)){const snap=snapPoint(raw);cursor=snap.point;state.snapMarker=snap.snapped?cursor:null;renderOverlay()}$('#coords').innerHTML=`x ${Math.round(cursor.x)} &nbsp; y ${Math.round(cursor.y)}`;if(state.tool==='pen'&&state.drawing){state.draft.push(raw);renderOverlay()}if(state.tool==='pan'&&state.drawing){$('#stageWrap').scrollLeft=state.pan.l-(ev.clientX-state.pan.x);$('#stageWrap').scrollTop=state.pan.t-(ev.clientY-state.pan.y)}});
