function crosses(a,b,c,d){const cc=(p1,p2,p3)=>(p3.y-p1.y)*(p2.x-p1.x)>(p2.y-p1.y)*(p3.x-p1.x);return cc(a,c,d)!==cc(b,c,d)&&cc(a,b,c)!==cc(a,b,d)}
function layoutRuleSummary(profile){const layout=tradeRegistry?.getLayoutProfile?.('railing',profile.layoutProfile||profile.id);if(!layout)return'';const sections=Object.entries(layout.sections||{}).map(([key,s])=>s?.pattern?`${key}: ${s.pattern}${Number.isFinite(s.overall)?` = ${s.overall}″ OAL`:''}`:'').filter(Boolean);const max=layout.maxBay? `Max bay ${layout.maxBay}″`:'';const ground=layout.minGroundPostsPerSection? `min ${layout.minGroundPostsPerSection} ground posts/section`:'';return `<br><small><strong>Athena layout rules:</strong> ${[max,ground].filter(Boolean).join(' · ')}${sections.length?`<br>${sections.map(esc).join('<br>')}`:''}</small>`}
$('#calculateRail').onclick=()=>{const it=state.items.find(i=>i.id===state.selected);if(!it||!['length','multilength'].includes(it.type))return toast('Select a length or multi-segment rail run first');if(!state.scale)return toast('Calibrate the plan before calculating railing');const p=railProfiles.find(x=>x.id===$('#railProfile').value)||railProfiles[0],runSegs=it.type==='multilength'?it.segments:itemSegments(it),jointSegs=state.items.filter(x=>x.type==='joint'&&x.page===it.page).flatMap(itemSegments);let crossings=0;for(const a of runSegs)for(const b of jointSegs)if(crosses(a[0],a[1],b[0],b[1]))crossings++;const inches=linearValue(it)*12,corners=it.type==='length'?Math.max(0,it.points.length-2):0,piecesPerRail=Math.max(crossings+1,Math.ceil((inches+crossings*p.overlap)/p.stock)),railPieces=piecesPerRail*p.rails,posts=Math.ceil(inches/p.post)+1,sleeves=crossings*p.rails;$('#railResult').innerHTML=`<strong>${esc(p.name)}</strong><br>${(inches/12).toFixed(2)} LF run · ${railPieces} rail pieces · ${posts} posts<br>${sleeves} expansion sleeves · ${corners} corner bends${crossings?`<br><span class="warn">${crossings} expansion crossing${crossings===1?'':'s'}: solid pieces must break and sleeve.</span>`:''}<br><small>Max post spacing ${p.post}″ · bend-to-post ${p.bendPost}″ max · sleeve gap ${p.gap}″</small>${layoutRuleSummary(p)}`};
function paintPrintMarkup(c,pageNum){c.save();c.lineWidth=3;c.font='bold 14px Arial';c.lineJoin='round';for(const it of state.items.filter(i=>i.page===pageNum)){const color=colors[it.type]||colors.length;c.strokeStyle=color;c.fillStyle=color;c.setLineDash(it.type==='joint'?[10,7]:[]);if(it.type==='count'){c.beginPath();c.arc(it.points[0].x,it.points[0].y,10,0,Math.PI*2);c.fill();c.fillStyle='#111';c.textAlign='center';c.fillText(it.seq,it.points[0].x,it.points[0].y+5);continue}const groups=it.type==='multilength'?it.segments:[it.points];for(const pts of groups){c.beginPath();pts.forEach((p,n)=>n?c.lineTo(p.x,p.y):c.moveTo(p.x,p.y));if(it.type==='area')c.closePath();c.stroke()}const p=it.type==='multilength'?it.segments[0][1]:it.type==='angle'?it.points[1]:it.points[Math.floor(it.points.length/2)];c.textAlign='left';c.fillText(formatValue(it),p.x+8,p.y-8);if(it.railLayout?.notation)c.fillText(it.railLayout.notation,p.x+8,p.y+10)}c.setLineDash([]);c.strokeStyle=colors.pen;for(const st of state.strokes.filter(s=>s.page===pageNum)){c.beginPath();st.points.forEach((p,n)=>n?c.lineTo(p.x,p.y):c.moveTo(p.x,p.y));c.stroke()}c.restore()}
async function printablePage(n,markupOnly){const out=document.createElement('canvas'),o=out.getContext('2d');if(state.pdf){const p=await state.pdf.getPage(n),v=p.getViewport({scale:1.5});out.width=Math.round(v.width);out.height=Math.round(v.height);if(markupOnly){o.fillStyle='#fff';o.fillRect(0,0,out.width,out.height)}else await p.render({canvasContext:o,viewport:v}).promise}else{out.width=canvas.width;out.height=canvas.height;if(markupOnly){o.fillStyle='#fff';o.fillRect(0,0,out.width,out.height)}else o.drawImage(canvas,0,0)}paintPrintMarkup(o,n);return out.toDataURL('image/png')}
$('#printBtn').onclick=()=>{if(sheet.hidden)return toast('Open a plan first');$('#printModal').classList.add('show')};$('#cancelPrint').onclick=()=>$('#printModal').classList.remove('show');
$('#startPrint').onclick=async()=>{const w=window.open('','atlas-print');if(!w)return toast('Allow pop-ups to create the print view');$('#printModal').classList.remove('show');w.document.write('<title>Atlas Forge Markups</title><p style="font:16px sans-serif">Preparing marked-up plan…</p>');const scope=$('#printScope').value,nums=scope==='all'?Array.from({length:state.pages},(_,i)=>i+1):[state.page],markupOnly=$('#markupOnly').checked,images=[];for(const n of nums)images.push({n,url:await printablePage(n,markupOnly)});w.document.open();w.document.write(`<title>${esc(state.file)} — Atlas Forge Markups</title><style>@page{margin:.35in}body{margin:0;font-family:Arial}section{break-after:page}section:last-child{break-after:auto}img{width:100%;height:auto}header{font-size:12px;margin:0 0 8px;color:#333}</style>${images.map(x=>`<section><header>Atlas Forge · ${esc(state.file)} · Page ${x.n}</header><img src="${x.url}"></section>`).join('')}<script>addEventListener('load',()=>setTimeout(()=>print(),300))<\/script>`);w.document.close()};
const PROJECT_DB='atlas-forge-projects',PROJECT_STORE='projects';
let projectDbPromise=null,projectHydrating=false,autosaveTimer=null;
function openProjectDb(){if(projectDbPromise)return projectDbPromise;projectDbPromise=new Promise((resolve,reject)=>{const request=indexedDB.open(PROJECT_DB,1);request.onupgradeneeded=()=>{if(!request.result.objectStoreNames.contains(PROJECT_STORE))request.result.createObjectStore(PROJECT_STORE,{keyPath:'id'})};request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)});return projectDbPromise}
async function projectStore(mode,work){const db=await openProjectDb();return new Promise((resolve,reject)=>{const tx=db.transaction(PROJECT_STORE,mode),store=tx.objectStore(PROJECT_STORE);let result;try{result=work(store)}catch(error){reject(error);return}tx.oncomplete=()=>resolve(result?.result);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)})}
const projectOwner=()=>window.atlasForgeCurrentUser?.id||'local-user';
function portableDoc(d){return{file:d.file,mime:d.mime||d.source?.type||'',source:d.source,page:d.page,pages:d.pages,zoom:d.zoom,scale:d.scale,items:d.items,strokes:d.strokes,multiId:d.multiId,group:d.group||'General',split:!!d.split,splitPage:d.splitPage||Math.min(2,d.pages)}}
async function saveCurrentProject({silent=false}={}){captureDoc();if(!state.docs.length){if(!silent)toast('Open a plan before saving a project');return}const input=$('#projectName'),name=(input.value||state.projectName||state.file.replace(/\.[^.]+$/,'')||'Untitled project').trim();state.projectId=state.projectId||crypto.randomUUID();state.projectName=name;const record={id:state.projectId,ownerId:projectOwner(),name,updatedAt:new Date().toISOString(),activeDoc:Math.max(0,state.activeDoc),tradePack:state.tradePack,docs:state.docs.map(portableDoc)};await projectStore('readwrite',store=>store.put(record));input.value=name;$('#projectSaveState').textContent='Saved '+new Date(record.updatedAt).toLocaleTimeString([],{hour:'numeric',minute:'2-digit'});if(!silent){toast('Project saved on this device');await renderProjectList()}}
function scheduleProjectSave(){if(!state.projectId||projectHydrating)return;clearTimeout(autosaveTimer);autosaveTimer=setTimeout(()=>saveCurrentProject({silent:true}).catch(()=>{}),900)}
async function allProjects(){const rows=await projectStore('readonly',store=>store.getAll());return(rows||[]).filter(project=>project.ownerId===projectOwner()).sort((a,b)=>String(b.updatedAt).localeCompare(String(a.updatedAt)))}
async function runtimeDoc(saved){if(!saved.source)throw new Error('The original plan file is missing');const url=URL.createObjectURL(saved.source);let pdf=null,image=null,dxf=null,pages=saved.pages||1;try{if(saved.file.toLowerCase().endsWith('.dxf'))dxf=parseDxf(await saved.source.text());else if(saved.mime==='application/pdf'||saved.file.toLowerCase().endsWith('.pdf')){if(!pdfjs)throw new Error('PDF viewer could not load');pdf=await pdfjs.getDocument(url).promise;pages=pdf.numPages}else image=await loadImage(url);return{...saved,objectUrl:url,pdf,image,dxf,cadPoints:[] ,pages}}catch(error){URL.revokeObjectURL(url);throw error}}
async function openSavedProject(id){const project=await projectStore('readonly',store=>store.get(id));if(!project||project.ownerId!==projectOwner())return toast('Project could not be opened');projectHydrating=true;clearTimeout(autosaveTimer);for(const doc of state.docs)if(doc.objectUrl)URL.revokeObjectURL(doc.objectUrl);const docs=[];try{for(const saved of project.docs)docs.push(await runtimeDoc(saved));state.docs=docs;state.activeDoc=-1;state.projectId=project.id;state.projectName=project.name;state.tradePack=project.tradePack||'railing';$('#projectName').value=project.name;applyTradePack(state.tradePack,true);if(docs.length)await activateDoc(Math.min(project.activeDoc||0,docs.length-1));$('#projectsModal').classList.remove('show');toast('Project opened: '+project.name)}catch(error){toast(error.message||'Project could not be opened')}finally{projectHydrating=false}}
async function deleteSavedProject(id){const projects=await allProjects(),project=projects.find(item=>item.id===id);if(!project||!confirm(`Delete “${project.name}” from this device?`))return;await projectStore('readwrite',store=>store.delete(id));if(state.projectId===id){state.projectId=null;state.projectName=''}await renderProjectList();toast('Saved project deleted')}
async function renderProjectList(){const wrap=$('#projectList'),projects=await allProjects();wrap.innerHTML=projects.length?projects.map(project=>`<div class="project-card"><div><strong>${esc(project.name)}</strong><small>${project.docs.length} plan${project.docs.length===1?'':'s'} · updated ${new Date(project.updatedAt).toLocaleString()}</small></div><div class="control-row"><button class="btn" data-open-project="${project.id}">Open</button><button class="btn" data-delete-project="${project.id}">Delete</button></div></div>`).join(''):'<div class="empty-projects">No saved projects on this device yet.</div>';$$('[data-open-project]').forEach(button=>button.onclick=()=>openSavedProject(button.dataset.openProject));$$('[data-delete-project]').forEach(button=>button.onclick=()=>deleteSavedProject(button.dataset.deleteProject))}
async function showProjects(){const modal=$('#projectsModal');$('#projectName').value=state.projectName||state.file.replace(/\.[^.]+$/,'');$('#projectSaveState').textContent=state.projectId?'Autosave is on for this project.':'';modal.classList.add('show');$('#sidePanel').classList.remove('open');try{await renderProjectList()}catch{toast('Saved projects are unavailable in this browser')}}
$('#projectsBtn').onclick=showProjects;$('#mobileProjectsBtn').onclick=showProjects;$('#closeProjectsBtn').onclick=()=>$('#projectsModal').classList.remove('show');$('#saveProjectBtn').onclick=()=>saveCurrentProject().catch(()=>toast('Project could not be saved'));
const projectObserver=new MutationObserver(scheduleProjectSave);for(const node of [$('#measureList'),$('#scaleText'),$('#docBar')])if(node)projectObserver.observe(node,{childList:true,subtree:true,characterData:true});
renderLayoutProfileSelect();renderProfileSelect();applyTradePack(state.tradePack,true);syncLayoutProfileFromGroup(false);
$('#panelBtn').onclick=()=>$('#sidePanel').classList.toggle('open');
const betaAccessModal=$('#betaAccessModal');
function generateBetaPassword(){const chars='ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789!@$';const bytes=crypto.getRandomValues(new Uint8Array(18));return'Forge-'+Array.from(bytes,n=>chars[n%chars.length]).join('')}
function openBetaAccess(){if(!window.atlasForgeIsOwner)return;$('#betaPassword').value=generateBetaPassword();$('#betaAccessStatus').textContent='Copy this password before creating the accounts. It will not be emailed.';$('#betaAccessStatus').classList.remove('error');betaAccessModal.classList.add('show');$('#sidePanel').classList.remove('open')}
$('#betaAccessBtn').onclick=openBetaAccess;$('#mobileBetaAccessBtn').onclick=openBetaAccess;$('#closeBetaAccess').onclick=()=>betaAccessModal.classList.remove('show');$('#generateBetaPassword').onclick=()=>{$('#betaPassword').value=generateBetaPassword();$('#betaAccessStatus').textContent='New temporary password generated.'};
$('#createBetaAccounts').onclick=async()=>{const password=$('#betaPassword').value,button=$('#createBetaAccounts'),status=$('#betaAccessStatus');if(password.length<12){status.textContent='Use at least 12 characters.';status.classList.add('error');return}button.disabled=true;button.textContent='Creating…';status.textContent='';status.classList.remove('error');const result=await window.atlasForgeProvisionBeta?.(password);button.disabled=false;button.textContent='Create four accounts';if(!result||result.error){status.textContent=result?.error||'The accounts could not be created.';status.classList.add('error');return}status.innerHTML=`Four accounts created. Access expires ${new Date(result.expires_at).toLocaleString()}. Keep the password above and share it yourself when ready.`;toast('Four beta accounts created')};
const guideModal=$('#guideModal'),feedbackModal=$('#feedbackModal');
function openGuide(){guideModal.classList.add('show');$('#sidePanel').classList.remove('open')}
function closeGuide(){guideModal.classList.remove('show');const id=window.atlasForgeCurrentUser?.id;if(id)localStorage.setItem('atlasForgeIntroV1:'+id,'seen')}
function openFeedback(type='bug'){feedbackModal.classList.add('show');$('#feedbackType').value=type;$('#feedbackStatus').textContent='';$('#feedbackStatus').classList.remove('error');$('#sidePanel').classList.remove('open');setTimeout(()=>$('#feedbackTitle').focus(),0)}
function closeFeedback(){feedbackModal.classList.remove('show')}
$('#guideBtn').onclick=openGuide;$('#mobileGuideBtn').onclick=openGuide;$('#closeGuideBtn').onclick=closeGuide;
$('#feedbackBtn').onclick=()=>openFeedback('bug');$('#mobileFeedbackBtn').onclick=()=>openFeedback('bug');
$('#guideFeedbackBtn').onclick=()=>{closeGuide();openFeedback('idea')};$('#cancelFeedbackBtn').onclick=closeFeedback;
$('#feedbackForm').addEventListener('submit',async e=>{
  e.preventDefault();
  const button=$('#submitFeedbackBtn'),status=$('#feedbackStatus');
  button.disabled=true;button.textContent='Sending…';status.textContent='';status.classList.remove('error');
  const result=await window.atlasForgeSubmitFeedback?.({feedbackType:$('#feedbackType').value,title:$('#feedbackTitle').value.trim(),details:$('#feedbackDetails').value.trim()});
  button.disabled=false;button.textContent='Send feedback';
  if(!result||result.error){status.textContent=result?.error||'Feedback could not be sent. Please try again.';status.classList.add('error');return}
  status.textContent='Thank you — your feedback was sent.';$('#feedbackForm').reset();
  setTimeout(closeFeedback,1200);
});
