window.addEventListener('keydown',e=>{if(e.key==='Escape'){state.draft=[];state.selected=null;renderOverlay()}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){$('#undoBtn').click()}if((e.key==='Delete'||e.key==='Backspace')&&state.tool==='select'&&state.selected&&!['INPUT','SELECT'].includes(document.activeElement.tagName)){state.items=state.items.filter(i=>i.id!==state.selected);state.selected=null;refreshUI()}if(e.key==='Enter'&&state.tool==='length'&&state.draft.length>=2)finishShape('length');if(e.key==='Enter'&&state.tool==='area'&&state.draft.length>=3)finishShape('area');if(e.key==='Enter'&&state.tool==='joint'&&state.draft.length>=2)finishShape('joint');if(e.key==='Enter'&&state.tool==='multilength'&&state.multiId){state.multiId=null;toast('Multi-segment takeoff complete')}});
